import { createVNode, Fragment } from '../create-element';
import { EMPTY_OBJ, EMPTY_ARR, IS_NON_DIMENSIONAL } from '../constants';
import { isArray, assign, removeNode } from '../util';
import options from '../options';
import { diffProps as diffHostProps, setProperty as setHostProperty } from './props';

const defer =
	typeof Promise == 'function'
		? Promise.prototype.then.bind(Promise.resolve())
		: setTimeout;

let hostedDiff = null;
let ComponentBase = null;

export function bindHostedDiff(fn) {
	hostedDiff = fn;
}

export function bindComponentBase(ctor) {
	ComponentBase = ctor;
}

/**
 * Coordinates child reconciliation, host property application, component
 * scheduling, vnode teardown, and commit flushing for a render tree.
 * @param {void} _unused
 */
export function Reconciler(_unused) {
	this.childParentDom = null;
	this.childRenderResult = null;
	this.childNewParent = null;
	this.childOldParent = null;
	this.childContext = null;
	this.childIsSvg = false;
	this.childExcess = null;
	this.childCommitQueue = null;
	this.childOldDom = null;
	this.childHydrating = false;
	this.childRefQueue = null;
	this.childSkew = 0;
	this.childOldChildren = null;
	this.childRemaining = 0;
	this.childFirstDom = null;
	this.childCurrent = null;
	this.childOldVNode = null;
	this.childMatchingIndex = -1;
	this.hostDom = null;
	this.hostNewProps = null;
	this.hostOldProps = null;
	this.hostIsSvg = false;
	this.hostHydrate = false;
	this.hostName = null;
	this.hostValue = null;
	this.hostOldValue = null;
	this.hostCapture = false;
	this.hostStyle = null;
	this.scheduleQueue = [];
	this.scheduleCount = 0;
	this.schedulePrevDebounce = undefined;
	this.scheduleCurrent = null;
	this.scheduleOldVNode = null;
	this.scheduleParentDom = null;
	this.teardownVNode = null;
	this.teardownParent = null;
	this.teardownSkip = false;
	this.teardownRef = null;
	this.commitList = null;
	this.commitRootNode = null;
	this.commitRefs = null;
	this.elementDom = null;
	this.elementNewVNode = null;
	this.elementOldVNode = null;
	this.elementContext = null;
	this.elementIsSvg = false;
	this.elementExcess = null;
	this.elementCommitQueue = null;
	this.elementHydrating = false;
	this.elementRefQueue = null;
	this.elementNodeType = null;
	this.childPhase = 'idle';
	this.hostPhase = 'idle';
	this.schedulePhase = 'idle';
	this.teardownPhase = 'idle';
	this.commitPhase = 'idle';
	this.elementPhase = 'idle';
}

Reconciler.prototype.captureChildSession = function (
	parentDom,
	renderResult,
	newParentVNode,
	oldParentVNode,
	globalContext,
	isSvg,
	excessDomChildren,
	commitQueue,
	oldDom,
	isHydrating,
	refQueue
) {
	this.childPhase = 'captureChildSession';
	this.childParentDom = parentDom;
	this.childRenderResult = renderResult;
	this.childNewParent = newParentVNode;
	this.childOldParent = oldParentVNode;
	this.childContext = globalContext;
	this.childIsSvg = isSvg;
	this.childExcess = excessDomChildren;
	this.childCommitQueue = commitQueue;
	this.childOldDom = oldDom;
	this.childHydrating = isHydrating;
	this.childRefQueue = refQueue;
	this.childSkew = 0;
	this.childFirstDom = null;
	this.childOldChildren =
		(oldParentVNode && oldParentVNode._children) || EMPTY_ARR;
	this.childRemaining = this.childOldChildren.length;
	if (this.childRenderResult == null) {
		this.childRenderResult = EMPTY_ARR;
	}
	return this.childOldChildren;
};

Reconciler.prototype.isIgnorableChild = function (childVNode) {
	this.childPhase = 'isIgnorableChild';
	this.childCurrent = childVNode;
	if (childVNode == null) {
		return true;
	}
	if (typeof childVNode == 'boolean') {
		return true;
	}
	if (typeof childVNode == 'function') {
		return true;
	}
	return false;
};

Reconciler.prototype.isTextLikeChild = function (childVNode) {
	this.childPhase = 'isTextLikeChild';
	this.childCurrent = childVNode;
	if (
		typeof childVNode == 'string' ||
		typeof childVNode == 'number' ||
		// eslint-disable-next-line valid-typeof
		typeof childVNode == 'bigint'
	) {
		return true;
	}
	return false;
};

Reconciler.prototype.wrapArrayChild = function (childVNode) {
	this.childPhase = 'wrapArrayChild';
	this.childCurrent = childVNode;
	if (!isArray(childVNode)) {
		return null;
	}
	return createVNode(Fragment, { children: childVNode }, null, null, null);
};

Reconciler.prototype.cloneOccupiedChild = function (childVNode) {
	this.childPhase = 'cloneOccupiedChild';
	this.childCurrent = childVNode;
	if (childVNode == null || childVNode._depth == null) {
		return null;
	}
	if (!(childVNode._depth > 0)) {
		return null;
	}
	return createVNode(
		childVNode.type,
		childVNode.props,
		childVNode.key,
		childVNode.ref ? childVNode.ref : null,
		childVNode._original
	);
};

/**
 * Normalize a child into a vnode the reconciler can diff.
 * @param {*} childVNode
 * @param {import('../internal').VNode} newParentVNode
 * @param {number} i
 */
Reconciler.prototype.coerceChild = function (childVNode, newParentVNode, i) {
	this.childPhase = 'coerceChild';
	this.childCurrent = childVNode;
	if (this.isIgnorableChild(childVNode)) {
		childVNode = newParentVNode._children[i] = null;
	}
	// If this newVNode is being reused (e.g. <div>{reuse}{reuse}</div>) in the same diff,
	// or we are rendering a component (e.g. setState) copy the oldVNodes so it can have
	// it's own DOM & etc. pointers
	else if (this.isTextLikeChild(childVNode)) {
		childVNode = newParentVNode._children[i] = createVNode(
			null,
			childVNode,
			null,
			null,
			childVNode
		);
	} else if (isArray(childVNode)) {
		childVNode = newParentVNode._children[i] = this.wrapArrayChild(childVNode);
	} else if (childVNode._depth > 0) {
		childVNode = newParentVNode._children[i] = this.cloneOccupiedChild(
			childVNode
		);
	} else {
		childVNode = newParentVNode._children[i] = childVNode;
	}
	this.childCurrent = childVNode;
	return childVNode;
};

Reconciler.prototype.skipMissingChild = function (
	oldChildren,
	i,
	oldParentVNode
) {
	this.childPhase = 'skipMissingChild';
	this.childOldVNode = oldChildren[i];
	let oldVNode = oldChildren[i];
	if (oldVNode && oldVNode.key == null && oldVNode._dom) {
		if (oldVNode._dom == this.childOldDom) {
			oldVNode._parent = oldParentVNode;
			this.childOldDom = this.findDomSibling(oldVNode);
		}
		this.unmount(oldVNode, oldVNode, false);
		oldChildren[i] = null;
	}
	return this.childOldDom;
};

Reconciler.prototype.attachChildMeta = function (childVNode, newParentVNode) {
	this.childPhase = 'attachChildMeta';
	this.childCurrent = childVNode;
	childVNode._parent = newParentVNode;
	childVNode._depth = newParentVNode._depth + 1;
	return childVNode;
};

Reconciler.prototype.matchesOldChild = function (childVNode, oldVNode) {
	this.childPhase = 'matchesOldChild';
	this.childOldVNode = oldVNode;
	if (oldVNode === null) {
		return true;
	}
	if (oldVNode && childVNode.key == oldVNode.key && childVNode.type === oldVNode.type) {
		return true;
	}
	return false;
};

Reconciler.prototype.searchAroundSkew = function (
	childVNode,
	oldChildren,
	skewedIndex,
	remainingOldChildren
) {
	this.childPhase = 'searchAroundSkew';
	this.childCurrent = childVNode;
	this.childMatchingIndex = -1;
	const key = childVNode.key;
	const type = childVNode.type;
	let x = skewedIndex - 1;
	let y = skewedIndex + 1;
	let oldVNode = oldChildren[skewedIndex];
	this.childOldVNode = oldVNode;

	while (x >= 0 || y < oldChildren.length) {
		if (x >= 0) {
			oldVNode = oldChildren[x];
			this.childOldVNode = oldVNode;
			if (oldVNode && key == oldVNode.key && type === oldVNode.type) {
				this.childMatchingIndex = x;
				return x;
			}
			x--;
		}

		if (y < oldChildren.length) {
			oldVNode = oldChildren[y];
			this.childOldVNode = oldVNode;
			if (oldVNode && key == oldVNode.key && type === oldVNode.type) {
				this.childMatchingIndex = y;
				return y;
			}
			y++;
		}
	}

	this.childMatchingIndex = -1;
	return -1;
};

Reconciler.prototype.findMatchingIndex = function (
	childVNode,
	oldChildren,
	skewedIndex,
	remainingOldChildren
) {
	this.childPhase = 'findMatchingIndex';
	this.childCurrent = childVNode;
	let oldVNode = oldChildren[skewedIndex];
	this.childOldVNode = oldVNode;

	if (this.matchesOldChild(childVNode, oldVNode)) {
		this.childMatchingIndex = skewedIndex;
		return skewedIndex;
	} else if (remainingOldChildren > (oldVNode != null ? 1 : 0)) {
		return this.searchAroundSkew(
			childVNode,
			oldChildren,
			skewedIndex,
			remainingOldChildren
		);
	}

	this.childMatchingIndex = -1;
	return -1;
};

Reconciler.prototype.resolveOldChild = function (
	childVNode,
	oldChildren,
	skewedIndex
) {
	this.childPhase = 'resolveOldChild';
	this.childCurrent = childVNode;
	const matchingIndex = this.findMatchingIndex(
		childVNode,
		oldChildren,
		skewedIndex,
		this.childRemaining
	);
	this.childMatchingIndex = matchingIndex;
	let oldVNode;
	if (matchingIndex === -1) {
		oldVNode = EMPTY_OBJ;
	} else {
		oldVNode = oldChildren[matchingIndex] || EMPTY_OBJ;
		oldChildren[matchingIndex] = undefined;
		this.childRemaining--;
	}
	this.childOldVNode = oldVNode;
	return oldVNode;
};

Reconciler.prototype.invokeChildPatch = function (
	parentDom,
	childVNode,
	oldVNode,
	globalContext,
	isSvg,
	excessDomChildren,
	commitQueue,
	oldDom,
	isHydrating,
	refQueue
) {
	this.childPhase = 'invokeChildPatch';
	this.childCurrent = childVNode;
	this.childOldVNode = oldVNode;
	hostedDiff(
		parentDom,
		childVNode,
		oldVNode,
		globalContext,
		isSvg,
		excessDomChildren,
		commitQueue,
		oldDom,
		isHydrating,
		refQueue
	);
	return childVNode._dom;
};

Reconciler.prototype.queueChildRef = function (
	childVNode,
	oldVNode,
	newDom,
	refQueue
) {
	this.childPhase = 'queueChildRef';
	this.childCurrent = childVNode;
	let j = childVNode.ref;
	if (j && oldVNode.ref != j) {
		if (oldVNode.ref) {
			this.applyRef(oldVNode.ref, null, childVNode);
		}
		refQueue.push(j, childVNode._component || newDom, childVNode);
		return true;
	}
	return false;
};

Reconciler.prototype.rememberFirstDom = function (newDom) {
	this.childPhase = 'rememberFirstDom';
	if (newDom != null && this.childFirstDom == null) {
		this.childFirstDom = newDom;
	}
	return this.childFirstDom;
};

Reconciler.prototype.isMountingChild = function (oldVNode) {
	this.childPhase = 'isMountingChild';
	this.childOldVNode = oldVNode;
	if (oldVNode === EMPTY_OBJ) {
		return true;
	}
	if (oldVNode._original === null) {
		return true;
	}
	return false;
};

Reconciler.prototype.adjustChildSkew = function (
	matchingIndex,
	skewedIndex,
	isMounting,
	remainingOldChildren,
	newChildrenLength
) {
	this.childPhase = 'adjustChildSkew';
	let skew = this.childSkew;
	if (isMounting) {
		if (matchingIndex == -1) {
			skew--;
		}
	} else if (matchingIndex !== skewedIndex) {
		if (matchingIndex === skewedIndex + 1) {
			skew++;
		} else if (matchingIndex > skewedIndex) {
			if (remainingOldChildren > newChildrenLength - skewedIndex) {
				skew += matchingIndex - skewedIndex;
			} else {
				skew--;
			}
		} else if (matchingIndex < skewedIndex) {
			if (matchingIndex == skewedIndex - 1) {
				skew = matchingIndex - skewedIndex;
			} else {
				skew = 0;
			}
		} else {
			skew = 0;
		}
	}
	this.childSkew = skew;
	return skew;
};

Reconciler.prototype.placeChild = function (parentDom, newDom, oldDom) {
	this.childPhase = 'placeChild';
	this.childParentDom = parentDom;
	this.childOldDom = oldDom;
	if (oldDom == null || oldDom.parentNode !== parentDom) {
		parentDom.insertBefore(newDom, null);
	} else if (newDom != oldDom || newDom.parentNode == null) {
		parentDom.insertBefore(newDom, oldDom);
	}
	this.childOldDom = newDom.nextSibling;
	return this.childOldDom;
};

Reconciler.prototype.reorderChildren = function (childVNode, oldDom, parentDom) {
	this.childPhase = 'reorderChildren';
	this.childCurrent = childVNode;
	this.childOldDom = oldDom;
	this.childParentDom = parentDom;
	let c = childVNode._children;
	let tmp = 0;
	for (; c && tmp < c.length; tmp++) {
		let vnode = c[tmp];
		if (vnode) {
			vnode._parent = childVNode;
			if (typeof vnode.type == 'function') {
				oldDom = this.reorderChildren(vnode, oldDom, parentDom);
			} else {
				oldDom = this.placeChild(parentDom, vnode._dom, oldDom);
			}
		}
	}
	this.childOldDom = oldDom;
	return oldDom;
};

Reconciler.prototype.placeOrReorderChild = function (
	childVNode,
	oldVNode,
	matchingIndex,
	skewedIndex,
	isMounting,
	newDom,
	oldDom,
	parentDom
) {
	this.childPhase = 'placeOrReorderChild';
	this.childCurrent = childVNode;
	this.childOldVNode = oldVNode;
	if (
		typeof childVNode.type == 'function' &&
		(matchingIndex !== skewedIndex ||
			oldVNode._children === childVNode._children)
	) {
		oldDom = this.reorderChildren(childVNode, oldDom, parentDom);
	} else if (
		typeof childVNode.type != 'function' &&
		(matchingIndex !== skewedIndex || isMounting)
	) {
		oldDom = this.placeChild(parentDom, newDom, oldDom);
	} else if (childVNode._nextDom !== undefined) {
		oldDom = childVNode._nextDom;
		childVNode._nextDom = undefined;
	} else {
		oldDom = newDom.nextSibling;
	}
	this.childOldDom = oldDom;
	return oldDom;
};

Reconciler.prototype.finishChildPass = function (newParentVNode) {
	this.childPhase = 'finishChildPass';
	this.childNewParent = newParentVNode;
	newParentVNode._dom = this.childFirstDom;
	return this.childFirstDom;
};

Reconciler.prototype.dropRemainingOldChildren = function (
	oldChildren,
	oldChildrenLength,
	newParentVNode
) {
	this.childPhase = 'dropRemainingOldChildren';
	this.childOldChildren = oldChildren;
	this.childNewParent = newParentVNode;
	for (let i = oldChildrenLength; i--; ) {
		if (oldChildren[i] != null) {
			if (
				typeof newParentVNode.type == 'function' &&
				oldChildren[i]._dom != null &&
				oldChildren[i]._dom == newParentVNode._nextDom
			) {
				newParentVNode._nextDom = oldChildren[i]._dom.nextSibling;
			}
			this.unmount(oldChildren[i], oldChildren[i]);
		}
	}
};

/**
 * Diff the children of a virtual node
 */
Reconciler.prototype.diffChildren = function (
	parentDom,
	renderResult,
	newParentVNode,
	oldParentVNode,
	globalContext,
	isSvg,
	excessDomChildren,
	commitQueue,
	oldDom,
	isHydrating,
	refQueue
) {
	this.childPhase = 'diffChildren';
	let i,
		oldVNode,
		childVNode,
		newDom,
		firstChildDom,
		skew = 0;

	let oldChildren = this.captureChildSession(
		parentDom,
		renderResult,
		newParentVNode,
		oldParentVNode,
		globalContext,
		isSvg,
		excessDomChildren,
		commitQueue,
		oldDom,
		isHydrating,
		refQueue
	);

	let oldChildrenLength = oldChildren.length,
		remainingOldChildren = oldChildrenLength,
		newChildrenLength = renderResult.length;

	this.childRemaining = remainingOldChildren;
	this.childSkew = skew;

	newParentVNode._children = [];
	for (i = 0; i < newChildrenLength; i++) {
		childVNode = renderResult[i];
		childVNode = this.coerceChild(childVNode, newParentVNode, i);

		if (childVNode == null) {
			this.skipMissingChild(oldChildren, i, oldParentVNode);
			oldDom = this.childOldDom;
			continue;
		}

		this.attachChildMeta(childVNode, newParentVNode);

		let skewedIndex = i + this.childSkew;
		oldVNode = this.resolveOldChild(childVNode, oldChildren, skewedIndex);
		let matchingIndex = this.childMatchingIndex;
		remainingOldChildren = this.childRemaining;

		newDom = this.invokeChildPatch(
			parentDom,
			childVNode,
			oldVNode,
			globalContext,
			isSvg,
			excessDomChildren,
			commitQueue,
			oldDom,
			isHydrating,
			refQueue
		);

		this.queueChildRef(childVNode, oldVNode, newDom, refQueue);

		if (newDom != null) {
			if (firstChildDom == null) {
				firstChildDom = newDom;
			}
			this.rememberFirstDom(firstChildDom);

			let isMounting = this.isMountingChild(oldVNode);
			this.adjustChildSkew(
				matchingIndex,
				skewedIndex,
				isMounting,
				remainingOldChildren,
				newChildrenLength
			);
			skew = this.childSkew;
			skewedIndex = i + skew;

			oldDom = this.placeOrReorderChild(
				childVNode,
				oldVNode,
				matchingIndex,
				skewedIndex,
				isMounting,
				newDom,
				oldDom,
				parentDom
			);

			if (typeof newParentVNode.type == 'function') {
				newParentVNode._nextDom = oldDom;
			}
		}
		this.childOldDom = oldDom;
	}

	this.childFirstDom = firstChildDom;
	this.finishChildPass(newParentVNode);
	this.dropRemainingOldChildren(
		oldChildren,
		oldChildrenLength,
		newParentVNode
	);
};

Reconciler.prototype.pushFlattenedChild = function (children, out) {
	this.childPhase = 'pushFlattenedChild';
	this.childCurrent = children;
	if (children == null || typeof children == 'boolean') {
		return out;
	}
	if (isArray(children)) {
		children.some(child => {
			this.toChildArray(child, out);
		});
		return out;
	}
	out.push(children);
	return out;
};

Reconciler.prototype.toChildArray = function (children, out) {
	this.childPhase = 'toChildArray';
	this.childCurrent = children;
	out = out || [];
	return this.pushFlattenedChild(children, out);
};

Reconciler.prototype.captureHostSession = function (
	dom,
	newProps,
	oldProps,
	isSvg,
	hydrate
) {
	this.hostPhase = 'captureHostSession';
	this.hostDom = dom;
	this.hostNewProps = newProps;
	this.hostOldProps = oldProps;
	this.hostIsSvg = isSvg;
	this.hostHydrate = hydrate;
	return dom;
};

Reconciler.prototype.shouldRemoveOldProp = function (name, newProps) {
	this.hostPhase = 'shouldRemoveOldProp';
	this.hostName = name;
	if (name === 'children') {
		return false;
	}
	if (name === 'key') {
		return false;
	}
	if (name in newProps) {
		return false;
	}
	return true;
};

Reconciler.prototype.shouldApplyNewProp = function (
	name,
	newProps,
	oldProps,
	hydrate
) {
	this.hostPhase = 'shouldApplyNewProp';
	this.hostName = name;
	if (hydrate && typeof newProps[name] != 'function') {
		return false;
	}
	if (name === 'children' || name === 'key') {
		return false;
	}
	if (name === 'value' || name === 'checked') {
		return false;
	}
	if (oldProps[name] === newProps[name]) {
		return false;
	}
	return true;
};

Reconciler.prototype.isCustomStyleProperty = function (key) {
	this.hostPhase = 'isCustomStyleProperty';
	this.hostName = key;
	if (key != null && key[0] === '-') {
		return true;
	}
	return false;
};

Reconciler.prototype.isNonDimensionalStyle = function (key) {
	this.hostPhase = 'isNonDimensionalStyle';
	this.hostName = key;
	if (typeof key != 'string') {
		return false;
	}
	return IS_NON_DIMENSIONAL.test(key);
};

Reconciler.prototype.setStyle = function (style, key, value) {
	this.hostPhase = 'setStyle';
	this.hostStyle = style;
	this.hostName = key;
	this.hostValue = value;
	if (this.isCustomStyleProperty(key)) {
		style.setProperty(key, value == null ? '' : value);
	} else if (value == null) {
		style[key] = '';
	} else if (typeof value != 'number' || this.isNonDimensionalStyle(key)) {
		style[key] = value;
	} else {
		style[key] = value + 'px';
	}
};

Reconciler.prototype.writeStyleText = function (dom, value) {
	this.hostPhase = 'writeStyleText';
	this.hostDom = dom;
	this.hostValue = value;
	dom.style.cssText = value;
};

Reconciler.prototype.clearMissingStyles = function (style, oldValue, value) {
	this.hostPhase = 'clearMissingStyles';
	this.hostStyle = style;
	this.hostOldValue = oldValue;
	this.hostValue = value;
	let name;
	for (name in oldValue) {
		if (!(value && name in value)) {
			this.setStyle(style, name, '');
		}
	}
};

Reconciler.prototype.assignChangedStyles = function (style, oldValue, value) {
	this.hostPhase = 'assignChangedStyles';
	this.hostStyle = style;
	this.hostOldValue = oldValue;
	this.hostValue = value;
	let name;
	for (name in value) {
		if (!oldValue || value[name] !== oldValue[name]) {
			this.setStyle(style, name, value[name]);
		}
	}
};

Reconciler.prototype.applyStyleProp = function (dom, value, oldValue) {
	this.hostPhase = 'applyStyleProp';
	this.hostDom = dom;
	this.hostValue = value;
	this.hostOldValue = oldValue;
	if (typeof value == 'string') {
		this.writeStyleText(dom, value);
		return;
	}
	if (typeof oldValue == 'string') {
		this.writeStyleText(dom, '');
		oldValue = '';
	}
	if (oldValue) {
		this.clearMissingStyles(dom.style, oldValue, value);
	}
	if (value) {
		this.assignChangedStyles(dom.style, oldValue, value);
	}
};

Reconciler.prototype.normalizeEventName = function (dom, name) {
